static esp_err_t thread_info_handler(httpd_req_t *req)
{
    if (!mesp_web_authorized(req)) return ESP_OK;
    Json j;
    j.obj().key("radio").str(mesp_thread_radio());
    if (!mesp_thread_ready()) {
        j.key("initialized").boolean(false).end_obj();
        return mesp_web_send_json(req, j.out());
    }
    {
        OtLock lock;
        otInstance *instance = esp_openthread_get_instance();
        j.key("initialized").boolean(otInstanceIsInitialized(instance));
        j.key("role").str(otThreadDeviceRoleToString(otThreadGetDeviceRole(instance)));
        j.key("commissioned").boolean(otDatasetIsCommissioned(instance));
        j.key("networkName").str(otThreadGetNetworkName(instance));
        j.key("channel").num(otLinkGetChannel(instance));
        char buf[40];
        snprintf(buf, sizeof(buf), "0x%04x", otLinkGetPanId(instance));
        j.key("panId").str(buf);
        const otExtendedPanId *xpan = otThreadGetExtendedPanId(instance);
        j.key("extPanId").hex(xpan->m8, sizeof(xpan->m8));
        snprintf(buf, sizeof(buf), "0x%04x", otThreadGetRloc16(instance));
        j.key("rloc16").str(buf);
        j.key("extAddress").hex(otLinkGetExtendedAddress(instance)->m8, OT_EXT_ADDRESS_SIZE);
        j.key("partitionId").unum(otThreadGetPartitionId(instance));
        j.key("leaderRouterId").num(otThreadGetLeaderRouterId(instance));

        otIp6Prefix omr;
        if (otBorderRoutingGetOmrPrefix(instance, &omr) == OT_ERROR_NONE) {
            char prefix[OT_IP6_PREFIX_STRING_SIZE];
            otIp6PrefixToString(&omr, prefix, sizeof(prefix));
            j.key("omrPrefix").str(prefix);
        }

        j.key("neighbors").arr();
        otNeighborInfoIterator it = OT_NEIGHBOR_INFO_ITERATOR_INIT;
        otNeighborInfo info;
        while (otThreadGetNextNeighborInfo(instance, &it, &info) == OT_ERROR_NONE) {
            j.obj();
            j.key("extAddress").hex(info.mExtAddress.m8, OT_EXT_ADDRESS_SIZE);
            snprintf(buf, sizeof(buf), "0x%04x", info.mRloc16);
            j.key("rloc16").str(buf);
            j.key("child").boolean(info.mIsChild);
            j.key("ftd").boolean(info.mFullThreadDevice);
            j.key("rxOnWhenIdle").boolean(info.mRxOnWhenIdle);
            j.key("rssi").num(info.mAverageRssi);
            j.key("lqi").num(info.mLinkQualityIn);
            j.key("age").num(info.mAge);
            j.key("version").num(info.mVersion);
            j.end_obj();
        }
        j.end_arr();

        j.key("children").arr();
        uint16_t max_children = otThreadGetMaxAllowedChildren(instance);
        for (uint16_t i = 0; i < max_children; i++) {
            otChildInfo child;
            if (otThreadGetChildInfoByIndex(instance, i, &child) != OT_ERROR_NONE) continue;
            j.obj();
            j.key("extAddress").hex(child.mExtAddress.m8, OT_EXT_ADDRESS_SIZE);
            snprintf(buf, sizeof(buf), "0x%04x", child.mRloc16);
            j.key("rloc16").str(buf);
            j.key("timeout").num(child.mTimeout);
            j.key("age").num(child.mAge);
            j.key("rssi").num(child.mAverageRssi);
            j.key("rxOnWhenIdle").boolean(child.mRxOnWhenIdle);
            j.end_obj();
        }
        j.end_arr();
        j.end_obj();
    }
    return mesp_web_send_json(req, j.out());
}

static esp_err_t thread_dataset_handler(httpd_req_t *req)
{
    if (!mesp_web_authorized(req)) return ESP_OK;
    uint8_t buf[OT_OPERATIONAL_DATASET_MAX_LENGTH];
    uint8_t len = 0;
    if (!mesp_thread_get_active_dataset(buf, &len)) {
        return mesp_web_send_error(req, "404 Not Found", "no active dataset");
    }
    Json j;
    j.obj().key("tlvs").hex(buf, len).end_obj();
    return mesp_web_send_json(req, j.out());
}

static esp_err_t thread_form_handler(httpd_req_t *req)
{
    if (!mesp_web_authorized(req)) return ESP_OK;
    // The panel picks up the result on its next poll.
    esp_err_t err = mesp_thread_form_network();
    if (err == ESP_ERR_INVALID_STATE) {
        return mesp_web_send_error(req, "503 Service Unavailable", "Thread radio is not connected");
    }
    if (err != ESP_OK) {
        return mesp_web_send_error(req, "500 Internal Server Error", esp_err_to_name(err));
    }
    return mesp_web_send_json(req, "{\"ok\":true}");
}

void mesp_thread_register_web()
{
    mesp_web_add("/api/thread", HTTP_GET, thread_info_handler);
    mesp_web_add("/api/thread/dataset", HTTP_GET, thread_dataset_handler);
    mesp_web_add("/api/thread/form", HTTP_POST, thread_form_handler);
}
